# Generated by the review-ignored-inks skill (.claude/skills/review-ignored-inks).
# Run __RUN_ID__, file __PART__: __SUMMARY__
#
# Dry run (default): all units run inside one transaction that is rolled back
# at the end, so later units see the effects of earlier ones; no jobs are
# enqueued. Rows it changes stay locked until it ends.
#   bin/rails runner path/to/this_file.rb
# Apply:
#   APPLY=1 bin/rails runner path/to/this_file.rb
# From a console: ENV["APPLY"] = "1" (or leave unset for a dry run), then
#   load "path/to/this_file.rb"
#
# Each unit (a merge of two macro clusters, a micro cluster, or all micro
# clusters of a new cluster) runs in its own transaction and is skipped when
# the clusters changed since the review. Merges run first and need the
# MergeMacroClusters operation; without it they are skipped.
# Every reviewed micro cluster gets an "IgnoredInkReview" agent log, which the
# next review run uses to skip clusters that were already looked at.
require "json"

lambda do
  run_id = "__RUN_ID__"
  apply = ENV["APPLY"] == "1"
  units = JSON.parse(<<~'DECISIONS')
    __DECISIONS__
  DECISIONS

  stats = Hash.new(0)
  prefix = apply ? "APPLIED" : "DRY-RUN"

  guard =
    lambda do |decision|
      micro_cluster = MicroCluster.find_by(id: decision["id"])
      next nil, "micro cluster missing" unless micro_cluster
      if micro_cluster
           .agent_logs
           .where(name: "IgnoredInkReview")
           .where("extra_data->>'run_id' = ?", run_id)
           .exists?
        next nil, "already applied in run #{run_id}"
      end
      next nil, "no longer ignored" unless micro_cluster.ignored?
      if micro_cluster.macro_cluster_id != decision["assigned_macro_id"]
        next nil, "macro cluster changed to #{micro_cluster.macro_cluster_id.inspect}"
      end

      [micro_cluster, nil]
    end

  review_log =
    lambda do |micro_cluster, decision, extra = {}|
      micro_cluster.agent_logs.create!(
        name: "IgnoredInkReview",
        state: AgentLog::APPROVED,
        approved_at: Time.current,
        agent_approved: decision["source"] != "human",
        transcript: [],
        extra_data: {
          "action" => decision["verdict"],
          "run_id" => run_id,
          "category" => decision["category"],
          "explanation_of_decision" => decision["reason"],
          "evidence" => decision["evidence"],
          "cluster_id" => decision["cluster_id"],
          "reviewed_users" => decision["users"],
          "source" => decision["source"]
        }.compact.merge(extra)
      )
    end

  # Same guidance log the admin UI writes when an ignore is undone, so a later
  # clusterer run is told not to ignore this ink again.
  rejected_ignore_log =
    lambda do |micro_cluster|
      micro_cluster.agent_logs.create!(
        name: "InkClusterer",
        state: AgentLog::REJECTED,
        rejected_at: Time.current,
        transcript: [],
        extra_data: {
          "action" => "ignore_ink"
        }
      )
    end

  # A macro cluster left without micro clusters is deleted unless it carries
  # reviews or a description; otherwise it is recalculated.
  release_macro_cluster =
    lambda do |macro_cluster_id, jobs|
      macro_cluster = MacroCluster.find_by(id: macro_cluster_id)
      next "macro cluster #{macro_cluster_id} already gone" unless macro_cluster

      if macro_cluster.micro_clusters.none? && macro_cluster.ink_reviews.none? &&
           macro_cluster.ink_review_submissions.none? && macro_cluster.description.blank?
        macro_cluster.destroy!
        "deleted empty macro cluster #{macro_cluster_id} (#{macro_cluster.name})"
      else
        jobs << [UpdateMacroCluster, macro_cluster_id]
        "macro cluster #{macro_cluster_id} keeps #{macro_cluster.micro_clusters.count} micro clusters"
      end
    end

  merge =
    lambda do |entry|
      unless defined?(MergeMacroClusters)
        puts "SKIP merge #{entry["from"]} -> #{entry["into"]}: MergeMacroClusters is not deployed yet"
        stats["skipped"] += 1
        next
      end
      source = MacroCluster.find_by(id: entry["from"])
      target = MacroCluster.find_by(id: entry["into"])
      unless source && target
        puts "SKIP merge #{entry["from"]} -> #{entry["into"]}: #{source ? "target" : "source"} missing (already merged?)"
        stats["skipped"] += 1
        next
      end

      source_name = source.name
      dropped =
        {
          "manual_brand_name" => source.manual_brand_name,
          "manual_line_name" => source.manual_line_name,
          "manual_ink_name" => source.manual_ink_name,
          "line_name_is_empty" => source.line_name_is_empty?,
          "description" => target.description.present? ? source.description : nil,
          "ignored_colors" => source.ignored_colors
        }.select { |_, value| value.present? }
      MergeMacroClusters.new(source, target).perform
      target.agent_logs.create!(
        name: "IgnoredInkReview",
        state: AgentLog::APPROVED,
        approved_at: Time.current,
        agent_approved: entry["source"] != "human",
        transcript: [],
        extra_data: {
          "action" => "merge",
          "run_id" => run_id,
          "merged_from" => entry["from"],
          "merged_from_name" => source_name,
          "dropped_from_source" => dropped,
          "explanation_of_decision" => entry["notes"]
        }
      )
      stats["merge"] += 1
      lost = dropped.any? ? "; source loses #{dropped.keys.join(", ")}" : ""
      puts "#{prefix} merge #{entry["from"]} (#{source_name}) -> #{target.id} (#{target.name})#{lost}"
    end

  process =
    lambda do |unit, jobs|
      if unit["merge"]
        merge.call(unit["merge"])
        next
      end

      if unit["group"]
        members =
          unit["members"].filter_map do |decision|
            micro_cluster, problem = guard.call(decision)
            puts "SKIP MC #{decision["id"]} (#{decision["name"]}): #{problem}" if problem
            stats["skipped"] += 1 if problem
            [micro_cluster, decision] if micro_cluster
          end
        next if members.empty?

        macro_cluster = MacroCluster.create!(ink_name: SecureRandom.uuid)
        members.each do |micro_cluster, decision|
          previous = micro_cluster.macro_cluster_id
          micro_cluster.update!(ignored: false, macro_cluster_id: macro_cluster.id)
          rejected_ignore_log.call(micro_cluster)
          review_log.call(
            micro_cluster,
            decision,
            "cluster_id" => macro_cluster.id,
            "group" => unit["group"]
          )
          note = previous ? "; #{release_macro_cluster.call(previous, jobs)}" : ""
          jobs << [UpdateMicroCluster, micro_cluster.id]
          stats["create"] += 1
          puts "#{prefix} MC #{micro_cluster.id} (#{decision["name"]}) -> new cluster #{macro_cluster.id} [#{unit["group"]}]#{note}"
        end
        next
      end

      decision = unit
      micro_cluster, problem = guard.call(decision)
      if problem
        puts "SKIP MC #{decision["id"]} (#{decision["name"]}): #{problem}"
        stats["skipped"] += 1
        next
      end

      previous = micro_cluster.macro_cluster_id
      case decision["verdict"]
      when "assign"
        target = MacroCluster.find_by(id: decision["cluster_id"])
        unless target
          puts "SKIP MC #{decision["id"]} (#{decision["name"]}): target #{decision["cluster_id"]} missing"
          stats["skipped"] += 1
          next
        end
        micro_cluster.update!(ignored: false, macro_cluster_id: target.id)
        rejected_ignore_log.call(micro_cluster)
        review_log.call(micro_cluster, decision)
        note =
          previous && previous != target.id ? "; #{release_macro_cluster.call(previous, jobs)}" : ""
        jobs << [UpdateMicroCluster, micro_cluster.id]
        puts "#{prefix} MC #{micro_cluster.id} (#{decision["name"]}) -> #{target.id} #{target.name}#{note}"
      when "unignore"
        micro_cluster.update!(ignored: false)
        rejected_ignore_log.call(micro_cluster)
        review_log.call(micro_cluster, decision, "cluster_id" => previous)
        jobs << [UpdateMicroCluster, micro_cluster.id]
        puts "#{prefix} MC #{micro_cluster.id} (#{decision["name"]}) unignored, stays in #{previous}"
      when "keep_ignored"
        if previous
          micro_cluster.update!(macro_cluster_id: nil)
          review_log.call(micro_cluster, decision, "unassigned_from" => previous)
          puts "#{prefix} MC #{micro_cluster.id} (#{decision["name"]}) unassigned from #{previous}; #{release_macro_cluster.call(previous, jobs)}"
        else
          review_log.call(micro_cluster, decision)
        end
      when "unsure"
        review_log.call(micro_cluster, decision)
      else
        raise ArgumentError,
              "Unknown verdict #{decision["verdict"].inspect} for MC #{decision["id"]}"
      end
      stats[decision["verdict"]] += 1
    end

  run_all =
    lambda do
      units.each do |unit|
        jobs = []
        ActiveRecord::Base.transaction(requires_new: true) { process.call(unit, jobs) }
        jobs.uniq.each { |worker, id| worker.perform_async(id) } if apply
      rescue ActiveRecord::ActiveRecordError => e
        stats["error"] += 1
        label =
          unit["merge"] ? "merge #{unit.dig("merge", "id")}" : unit["group"] || "MC #{unit["id"]}"
        puts "ERROR #{label}: #{e.class}: #{e.message}"
      end
    end

  if apply
    run_all.call
  else
    ActiveRecord::Base.transaction(requires_new: true) do
      run_all.call
      raise ActiveRecord::Rollback
    end
  end

  puts "#{apply ? "Applied" : "Dry run, nothing saved"}: #{stats.sort.map { |k, v| "#{k}=#{v}" }.join(" ")}"
end.call
